arguments.command:
python3 -c "
import pandas as pd
df = pd.read_pickle('df_cache.pkl')
glitches = [
 ('TURB_OUTPUT_01', pd.Timestamp('2024-01-15 18:00:00'), pd.Timestamp('2024-01-15 18:24:00')),
 ('STEAM_PRES_01', pd.Timestamp('2024-01-15 20:00:00'), pd.Timestamp('2024-01-15 20:19:00')),
 ('COOLING_PRES_01', pd.Timestamp('2024-01-16 00:10:00'), pd.Timestamp('2024-01-16 00:34:00')),
]
def is_glitch(sid, t):
    for gs, gt0, gt1 in glitches:
        if sid==gs and gt0<=t<=gt1:
            return True
    return False

for sid, g in df.groupby('sensor_id'):
    g = g.sort_values('utc_ts')
    mask = g['out_of_range'] & ~g['utc_ts'].apply(lambda t: is_glitch(sid, t))
    first = g[mask].head(1)
    if len(first):
        print(sid, first[['utc_ts','value','normal_min','normal_max']].to_string(index=False,header=False))
    else:
        print(sid, 'NONE')
"

